import type { OptimizeResponse } from '../types';

export type ServiceDay = 'weekday' | 'saturday' | 'sunday';
export type VolumeMode = 'uniform' | 'estimated' | 'measured' | 'ridership';

export interface PersistedAppState {
  maxShift: number;
  bufferMinutes: number;
  highFreqCutoff: number;
  tMax?: number;
  serviceDay: ServiceDay;
  volumeMode: VolumeMode;
  period: string;
  result: OptimizeResponse | null;
  resultPeriod?: string | null;
  resultServiceDay?: ServiceDay | null;
  highlightedRoute: string | null;
  minLayoverMinutes?: number | null;
  timeLimitSeconds?: number;
  maxConnections?: number | null;
}

// v2: dropped the pre-ridership-default persisted state (a stale
// 'estimated' volumeMode and a stale zero-savings result were overriding the
// flipped ridership default on reload). Existing v1 state is intentionally
// discarded so the new defaults apply for everyone.
const STATE_KEY = 'miway-app-state-v2';
const HELP_KEY = 'miway-getting-started-v1';

export function loadAppState(): Partial<PersistedAppState> | null {
  try {
    const raw = localStorage.getItem(STATE_KEY);
    if (!raw) return null;
    return JSON.parse(raw) as Partial<PersistedAppState>;
  } catch {
    return null;
  }
}

export function saveAppState(state: PersistedAppState): void {
  try {
    localStorage.setItem(STATE_KEY, JSON.stringify(state));
  } catch {
    // Quota exceeded or storage unavailable (private mode) — app still works
    // in-memory, persistence is best-effort.
  }
}

/** Best-effort hydration of a numeric control from persisted state. */
export function savedNum(
  saved: Partial<PersistedAppState> | null,
  key: keyof PersistedAppState,
  dflt: number,
): number {
  if (!saved) return dflt;
  const v = (saved as Record<string, unknown>)[key];
  return typeof v === 'number' ? v : dflt;
}

export function hasSeenGettingStarted(): boolean {
  try {
    return localStorage.getItem(HELP_KEY) === '1';
  } catch {
    return false;
  }
}

export function markGettingStartedSeen(): void {
  try {
    localStorage.setItem(HELP_KEY, '1');
  } catch {
    // ignore
  }
}
