import { Component, type ErrorInfo, type ReactNode } from 'react';

interface Props {
  children: ReactNode;
  /** Human label used in the fallback message, e.g. the panel name. */
  label?: string;
}

interface State {
  error: Error | null;
}

/**
 * Per-panel error boundary: a crash inside one view (bad API shape, null
 * deref in a chart) shows a contained fallback card instead of white-
 * screening the whole app. The user can retry in place or navigate away.
 */
export default class PanelErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // Console-only by design: no telemetry backend exists, and the boundary
    // itself must never be able to fail.
    console.error(`[PanelErrorBoundary${this.props.label ? `: ${this.props.label}` : ''}]`, error, info.componentStack);
  }

  private retry = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { label, children } = this.props;
    if (!error) return children;
    return (
      <div className="flex flex-col items-start gap-3 rounded-2xl border border-bottleneck/40 bg-card p-6">
        <div className="flex items-center gap-2 text-sm font-bold text-bottleneck">
          <span className="rounded-lg bg-bottleneck/15 p-1.5" aria-hidden="true">⚠</span>
          {label ? `${label} hit a snag` : 'This view hit a snag'}
        </div>
        <p className="text-xs leading-relaxed text-text-muted">
          {label ? `The ${label} view` : 'This view'} failed to render — everything else keeps
          working. The error is logged to the browser console; retry or come back later.
        </p>
        <pre className="max-h-32 max-w-full overflow-auto rounded-lg border border-border bg-bg px-3 py-2 text-[10px] leading-snug text-text-muted">
          {error.message}
        </pre>
        <div className="flex gap-2">
          <button
            onClick={this.retry}
            className="rounded-lg border border-optimized/40 bg-optimized/10 px-3 py-1.5 text-xs font-semibold text-optimized transition-colors hover:bg-optimized/20"
          >
            Try again
          </button>
        </div>
      </div>
    );
  }
}
