import { useEffect, useState } from 'react';
import { Activity } from 'lucide-react';
import { api } from '../lib/api';
import type { OperationsTrends, WeeklyRollupRow } from '../types';

/**
 * Home trends strip (T152c): "is service drifting week over week?" at a
 * glance. Aggregates the measured daily rollup rows into Monday-starting
 * weeks (weekday days only — the same comparability rule the backend's
 * week-over-week uses) and renders the last two complete weeks side by side.
 *
 * Reads the same data as ServiceQualityPanel/CoveragePanel
 * (api.operationsTrends → the collector's weekly_rollup.csv), so there is no
 * new endpoint, no new snapshot mapping, and no second source of truth. The
 * backend-side companion (build_weekly_trends.py) publishes the same
 * aggregation as a public data file (weekly-metrics.json) for the
 * reproducibility story; this component renders the live/snapshotted API so
 * it stays current between data-file refreshes.
 */

interface WeekAgg {
  weekStart: string;
  weekEnd: string;
  days: number;
  nRecorded: number;
  pctEarly: number | null;
  ghostRate: number | null;
}

const DAY_MS = 86_400_000;

function mondayOf(iso: string): string {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() - d.getUTCDay() + 1);
  return d.toISOString().slice(0, 10);
}

function aggregate(rows: WeeklyRollupRow[]): WeekAgg[] {
  const byWeek = new Map<string, WeeklyRollupRow[]>();
  for (const r of rows) {
    if (r.is_holiday) continue;
    const k = mondayOf(r.date);
    (byWeek.get(k) ?? byWeek.set(k, []).get(k)!).push(r);
  }
  const out: WeekAgg[] = [];
  for (const [k, weekRows] of byWeek) {
    const n = weekRows.reduce((s, r) => s + (r.n_recorded ?? 0), 0);
    const ver = weekRows.reduce((s, r) => s + (r.verifiable_trips ?? 0), 0);
    const gh = weekRows.reduce((s, r) => s + (r.ghost_trips ?? 0), 0);
    const earlyNum = weekRows.reduce(
      (s, r) => s + (r.pct_early_gt2 ?? 0) * (r.n_recorded ?? 0),
      0,
    );
    out.push({
      weekStart: k,
      weekEnd: new Date(new Date(k + 'T00:00:00Z').getTime() + 6 * DAY_MS)
        .toISOString()
        .slice(0, 10),
      days: weekRows.length,
      nRecorded: n,
      pctEarly: n ? earlyNum / n : null,
      ghostRate: ver ? (100 * gh) / ver : null,
    });
  }
  return out.sort((a, b) => a.weekStart.localeCompare(b.weekStart));
}

function pct(x: number | null, digits = 1): string {
  return x == null ? '—' : `${x.toFixed(digits)}%`;
}

function Delta({ now, prev, lowerIsBetter }: { now: number | null; prev: number | null; lowerIsBetter: boolean }) {
  if (now == null || prev == null || prev === 0) {
    return <span className="text-[10px] text-text-muted">vs last week —</span>;
  }
  const diff = now - prev;
  const good = lowerIsBetter ? diff < 0 : diff > 0;
  const neutral = Math.abs(diff) < (lowerIsBetter ? 0.1 : 0.05);
  const cls = neutral
    ? 'text-text-muted'
    : good
      ? 'text-optimized'
      : 'text-bottleneck';
  return (
    <span className={`text-[10px] font-semibold ${cls}`}>
      {diff >= 0 ? '+' : ''}
      {diff.toFixed(lowerIsBetter ? 1 : 2)}
      {lowerIsBetter ? ' pp' : ' pts'}
      <span className="font-normal text-text-muted"> vs last week</span>
    </span>
  );
}

export default function TrendsStrip() {
  const [data, setData] = useState<OperationsTrends | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [tick, setTick] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    setError(null);
    api
      .operationsTrends({ signal: controller.signal })
      .then(setData)
      .catch((e) => {
        if (!controller.signal.aborted) setError(String(e?.message ?? e));
      });
    return () => controller.abort();
  }, [tick]);

  if (error) {
    return (
      <section className="card-glow mt-4 overflow-hidden rounded-2xl border border-border bg-card p-4">
        <div className="flex items-center gap-2">
          <span className="rounded-lg bg-accent/15 p-1.5"><Activity className="h-4 w-4 text-accent" /></span>
          <h3 className="text-xs font-bold uppercase tracking-wide text-text-secondary">
            Measured service, week over week
          </h3>
        </div>
        <p className="mt-2 text-[11px] text-text-muted">
          Couldn't load the weekly rollup: {error}{' '}
          <button onClick={() => setTick((t) => t + 1)} className="underline">Retry</button>
        </p>
      </section>
    );
  }

  // Only COMPLETE weeks are comparable: a Monday-started week still collecting
  // (e.g. rendering on its first weekday) would show a partial-week delta that
  // is noise, not trend. Drop any week ending in the future.
  const todayIso = new Date().toISOString().slice(0, 10);
  const completeWeeks = data
    ? aggregate(data.rows).filter((w) => w.weekEnd <= todayIso)
    : null;
  const weeks = completeWeeks ? completeWeeks.slice(-2) : null;
  const prev = weeks?.[0];
  const curr = weeks?.[1];
  const ready = prev != null && curr != null;

  return (
    <section className="card-glow mt-4 overflow-hidden rounded-2xl border border-border bg-card">
      <div className="h-0.5 edge-gradient" />
      <div className="p-4">
        <div className="flex items-center gap-2">
          <span className="rounded-lg bg-accent/15 p-1.5">
            <Activity className="h-4 w-4 text-accent" />
          </span>
          <h3 className="text-xs font-bold uppercase tracking-wide text-text-secondary">
            Measured service, week over week
          </h3>
        </div>
        {data && data.available === false ? (
          <p className="mt-2 text-[11px] text-text-muted">
            Weekly rollup not available in this environment.
          </p>
        ) : !ready ? (
          <p className="mt-2 text-[11px] text-text-muted">
            {data ? 'Two complete weeks of measured days are needed before a week-over-week comparison can render.' : 'Loading…'}
          </p>
        ) : (
          <>
            <div className="mt-3 grid grid-cols-3 gap-2">
              {/* Early departures */}
              <div className="rounded-xl border border-border bg-bg/40 px-3 py-2.5">
                <div className="text-[10px] font-semibold uppercase tracking-wide text-text-muted">Early departures</div>
                <div className="mt-0.5 text-lg font-bold tabular-nums text-text-primary">{pct(curr.pctEarly)}</div>
                <Delta now={curr.pctEarly} prev={prev.pctEarly} lowerIsBetter />
              </div>
              {/* Ghost rate */}
              <div className="rounded-xl border border-border bg-bg/40 px-3 py-2.5">
                <div className="text-[10px] font-semibold uppercase tracking-wide text-text-muted">Ghost buses</div>
                <div className="mt-0.5 text-lg font-bold tabular-nums text-text-primary">{pct(curr.ghostRate, 2)}</div>
                <Delta now={curr.ghostRate} prev={prev.ghostRate} lowerIsBetter />
              </div>
              {/* Recorded departures */}
              <div className="rounded-xl border border-border bg-bg/40 px-3 py-2.5">
                <div className="text-[10px] font-semibold uppercase tracking-wide text-text-muted">Departures logged</div>
                <div className="mt-0.5 text-lg font-bold tabular-nums text-text-primary">
                  {(curr.nRecorded / 1_000_000).toFixed(2)}M
                </div>
                <span className="text-[10px] text-text-muted">{curr.days} weekdays · {curr.weekStart}</span>
              </div>
            </div>
            <p className="mt-2 text-[10px] leading-relaxed text-text-muted">
              Weeks ending {prev.weekEnd} → {curr.weekEnd}. Early = departing ≥2 min before schedule.
              A ghost is a scheduled trip with no observed bus — collector downtime never counts.
            </p>
          </>
        )}
      </div>
    </section>
  );
}
